   "sez": "prima",
   "titolo": "Canarie, circa 1.500 migranti approdati nell'arcipelago in una sola giornata",
   "orig": "Nearly 1,500 migrants reach Spain’s Canary Islands in one day",
   "lead": "Quasi 1.500 migranti sono giunti sulle coste delle Isole Canarie nell'arco di ventiquattro ore a bordo di diverse imbarcazioni. Secondo quanto documentato dai soccorritori, la maggior parte delle persone arrivate nel fine settimana proviene da Senegal, Gambia e Guinea. Questo forte aumento degli sbarchi sulle isole spagnole nell'Atlantico si registra poco dopo la recente emergenza migratoria che ha interessato l'enclave di Ceuta, confermando la costante pressione delle rotte verso la Spagna.",
   "more": [
    "La rotta atlantica verso le Canarie è considerata tra le più pericolose al mondo a causa delle forti correnti oceaniche e delle precarie condizioni delle imbarcazioni utilizzate per traversate di centinaia di chilometri. L'instabilità politica ed economica in diversi Paesi dell'Africa occidentale continua a spingere migliaia di persone a tentare la traversata."
   ],
