   "id": "z607730e6",
   "sez": "sport",
   "titolo": "Ronaldinho torna in campo a 46 anni con la maglia del Ravenna",
   "orig": "Il tempo di Ronaldinho. A Ravenna classe e sorrisi: “È stata l’ultima? Chissà...”",
   "lead": "A quarantasei anni di età e a oltre un decennio dall'ultima apparizione agonistica, Ronaldinho è tornato sul terreno di gioco indossando la maglia del Ravenna. Il fuoriclasse brasiliano ha partecipato all'azione che ha sbloccato la gara portando i padroni di casa sull'uno a zero, mostrando colpi tecnici e la consueta serenità durante il match. Nel dopopartita, commentando la prestazione, l'ex Pallone d'Oro non ha chiarito se si sia trattato di un'esperienza isolata o di un percorso più lungo. Lo riferisce la Repubblica.",
   "more": [
    "Ronaldinho è stato una delle figure più celebri del calcio mondiale nei primi anni Duemila, protagonista con il Barcellona, il Milan e la nazionale brasiliana, con cui ha vinto il Mondiale nel 2002. Il suo stile di gioco, incentrato su dribbling spettacolari e inventiva, lo ha reso un'icona globale anche dopo il ritiro dalle competizioni ad alti livelli."
   ],
