   "sez": "ambiente",
   "titolo": "Scozia, oltre 76.000 scarichi fognari non monitorati registrati dalle analisi",
   "orig": "How many sewage spills have happened in your part of Scotland?",
   "lead": "Un'indagine condotta da BBC Scotland News ha rivelato che oltre 76.000 scarichi di acque fognarie sono avvenuti presso siti di sfioro che in precedenza non erano soggetti a monitoraggio da parte dell'ente idrico Scottish Water. I dati mostrano l'estensione degli sversamenti reflui nei corsi d'acqua scozzesi, sollevando preoccupazioni per l'impatto ambientale sulle comunità locali e accendendo l'attenzione dei residenti sulla gestione delle infrastrutture idriche e fognarie del territorio. Lo riferisce BBC News.",
   "more": [
    "I sistemi di sfioro fognario fungono da valvole di sicurezza per evitare che le condutture urbane si allaghino durante piogge torrenziali, scaricando l'eccesso direttamente nei fiumi o in mare. L'assenza di sensori in molti di questi punti rende complessa la valutazione dei danni ecologici effettivi e ritarda gli investimenti necessari per l'adeguamento della rete fognaria."
   ],
