   "id": "zd7114bf5",
   "sez": "economia",
   "titolo": "Liberia, l'opposizione contesta la manovra 2027: \"Ignora gli allarmi sulla povertà\"",
   "orig": "Liberia: PLP Criticizes Boakai’s Spending Plan for 2027, Says Budget Ignores World Bank’s Warnings",
   "lead": "A Monrovia il People's Liberation Party ha contestato la proposta di bilancio nazionale per il 2027 presentata dall'amministrazione del presidente Joseph Boakai, sostenendo che le priorità di spesa non rispondano all'aggravarsi della povertà nel Paese. Secondo il partito d'opposizione, la pianificazione economica formulata dal governo trascurerebbe le raccomandazioni e gli avvertimenti formulati dalla Banca Mondiale sulle condizioni di vita della popolazione liberiana, chiedendo una revisione delle allocazioni destinate ai servizi fondamentali. Lo riferisce FrontPage Africa.",
   "more": [
    "La Liberia è uno Stato dell'Africa occidentale che affronta delicate sfide economiche legate all'inflazione, alla carenza di entrate statali e alla debolezza dei servizi di base. I bilanci pubblici del Paese dipendono in misura rilevante dal supporto delle istituzioni multilaterali, le cui indicazioni orientano spesso la sostenibilità fiscale e le politiche di spesa sociale."
   ],
