   "id": "z980e881c",
   "sez": "ambiente",
   "titolo": "Kenya, timori per l'impatto di El Niño: attese piogge intense e inondazioni",
   "orig": "'It can kill us': Kenyans fear impact of El Niño with floods predicted",
   "lead": "I meteorologi hanno avvertito che l'attuale fenomeno di El Niño potrebbe rivelarsi uno dei più violenti mai registrati, suscitando forti apprensioni tra la popolazione del Kenya per l'arrivo di abbondanti precipitazioni e diffuse inondazioni. Gli esperti temono che la combinazione di nubifragi e dissesto idrogeologico possa causare devastazioni alle coltivazioni, interruzioni delle vie di comunicazione e rischi per l'incolumità dei residenti nelle zone più esposte. Lo riferisce BBC News.",
   "more": [
    "El Niño è un fenomeno climatico periodico legato al riscaldamento anomalo delle acque superficiali dell'Oceano Pacifico equatoriale. Questa variazione altera la circolazione atmosferica globale, provocando gravi siccità in alcune aree del pianeta e precipitazioni estreme con alluvioni in altre, con ripercussioni severe sull'agricoltura dell'Africa orientale."
   ],
