   "orig": "Festival de futebol feminino de várzea reúne 1,5 mil atletas em SP",
   "lead": "Il Festival Feminino de Várzea ha riunito circa 1.500 atlete a San Paolo, presso il Parque Sete Campos, per una giornata all'insegna del calcio amatoriale femminile. La manifestazione ha visto la partecipazione di novantasei squadre senza il ricorso a sponsor commerciali ed è stata aperta al pubblico gratuitamente. L'evento ha ricevuto il sostegno della Federazione calcistica paulista, che ha designato terne arbitrali interamente composte da donne per dirigere le partite del torneo. Lo riferisce Agência Brasil.",
