   "id": "zb140851b",
   "sez": "cultura",
   "titolo": "New York, riscoperto in un armadio un quadro di Georgia O'Keeffe dal valore milionario",
   "orig": "‘There’s a Georgia O’Keeffe in the Closet’ – Words that Led to Painting’s Joyous Rediscovery",
   "lead": "Un dipinto attribuito alla celebre pittrice statunitense Georgia O'Keeffe è stato ritrovato nell'armadio di un appartamento dell'East Village a Manhattan, dove era rimasto nascosto per decenni dietro a cappotti e scatoloni. La scoperta è avvenuta casualmente durante le operazioni di sgombero dell'abitazione di un'anziana zia, che ha semplicemente fatto notare la presenza della tela. L'opera d'arte, custodita senza particolari protezioni per lungo tempo, ha un valore stimato di milioni di dollari sul mercato antiquario.",
   "more": [
    "Georgia O'Keeffe è considerata una delle figure di punta del modernismo americano, celebre per i dipinti ingranditi di fiori, i grattacieli newyorkesi e i paesaggi rocciosi del Nuovo Messico. I suoi lavori raggiungono quotazioni di primo piano nelle aste internazionali, e i ritrovamenti di opere rimaste inedite per decenni costituiscono eventi rari per la storia dell'arte."
   ],
