   "id": "z066c827b",
   "sez": "ambiente",
   "titolo": "Indonesia, il presidente Prabowo si scusa con Singapore e Malaysia per i fumi dei roghi",
   "orig": "Indonesia’s Prabowo apologises to Singapore, Malaysia over transboundary haze",
   "lead": "Il presidente indonesiano Prabowo Subianto ha espresso le scuse ufficiali a Singapore e alla Malaysia per i disagi provocati dai fumi transfrontalieri causati dagli incendi boschivi che continuano a divampare nel suo Paese. La dichiarazione è stata diffusa dalla presidenza al termine della prima giornata del vertice dei leader dell'Asean a Manila. Prabowo ha assicurato ai partner regionali che Giacarta sta compiendo tutti gli sforzi necessari per spegnere i roghi e contrastare l'inquinamento atmosferico che soffoca l'area. Lo riferisce South China Morning Post.",
   "more": [
    "La combustione di torbiere e foreste tropicali in Indonesia, spesso avviata per fare spazio a piantagioni agricole, genera periodicamente dense coltri di fumo che il vento trasporta nei Paesi confinanti. Questo fenomeno causa problemi respiratori a milioni di cittadini e tensioni diplomatiche costanti all'interno dell'Associazione delle Nazioni del Sud-Est Asiatico."
   ],
