   "id": "z8dadc199",
   "sez": "adolescenti",
   "titolo": "Validation seeking tra i giovani: quando il valore personale dipende dal giudizio altrui",
   "orig": "Validation seeking, il bisogno di piacere a tutti: quando i giovani confondono il riconoscimento con il proprio valore",
   "lead": "La ricerca costante di approvazione sociale, definita \"validation seeking\", spinge molti giovani a identificare il proprio valore esclusivamente con il consenso ottenuto da familiari, compagni o gruppi di pari. Se il desiderio di riconoscimento sostiene la maturazione personale, esso può trasformarsi in una gabbia quando il giudizio degli altri diventa l'unica misura della propria autostima. La riflessione evidenzia come le aspettative e il timore di non piacere rischino di compromettere lo sviluppo dell'identità giovanile. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Nell'età dell'adolescenza la costruzione dell'identità personale passa attraverso il confronto continuo con il gruppo dei pari e con le figure adulte di riferimento. L'uso intensivo dei social network, dove like e commenti quantificano visibilmente il gradimento, può amplificare il bisogno di convalida esterna, generando ansia da prestazione e fragilità emotiva."
   ],
