   "orig": "Phoebe Bridgers Stuns With Haunting Black-Light Skeleton Performance on ‘SNL’: Watch",
   "lead": "La cantautrice statunitense Phoebe Bridgers ha proposto un'esibizione di grande impatto visivo durante la trasmissione Saturday Night Live, utilizzando scheletri fluorescenti e luci nere sul palco. Nel corso della puntata del 14 novembre l'artista ha eseguito dal vivo due brani estratti dal suo recente album intitolato Lost Weekend, attirando commenti favorevoli per la cura scenica e l'atmosfera creata in studio durante la diretta televisiva. Lo riferisce Billboard.",
