   "id": "zcae336d4",
   "sez": "ambiente",
   "titolo": "Allarme siccità nelle Marianne Settentrionali e a Guam per il prolungarsi di El Niño",
   "orig": "El Niño could last until May 2027, raising drought fears in Northern Marianas and Guam",
   "lead": "Il fenomeno climatico El Niño potrebbe protrarsi fino al mese di maggio del 2027, provocando gravi ripercussioni meteorologiche nelle Isole Marianne Settentrionali e a Guam. Gli esperti segnalano il rischio concreto di una stagione secca eccezionalmente lunga e severa, caratterizzata da una diffusa siccità, da una marcata carenza di risorse idriche e da un conseguente aumento del pericolo di incendi boschivi sul territorio. L'intensità e la persistenza dell'anomalia mettono in allarme le autorità locali per la tenuta degli approvvigionamenti di acqua potabile. Lo riferisce RNZ.",
   "more": [
    "El Niño è un periodico riscaldamento delle acque superficiali dell'Oceano Pacifico equatoriale che altera la circolazione atmosferica globale. Nelle isole del Pacifico occidentale questo fenomeno determina spesso una drastica riduzione delle precipitazioni stagionali, abbassando la ricarica delle falde acquifere e inaridendo la vegetazione."
   ],
