   "id": "zf35e22fa",
   "sez": "adolescenti",
   "titolo": "La valutazione scolastica deve sostenere le inclinazioni individuali secondo il presidente Invalsi",
   "orig": "INVALSI, il presidente Ricci: “La valutazione deve tutelare le competenze di base ma anche sostenere le inclinazioni individuali” (VIDEO)",
   "lead": "Il presidente dell'Invalsi, Roberto Ricci, ha sottolineato l'esigenza di ripensare il sistema di valutazione scolastica affinché non si limiti a essere una fotografia statica del rendimento degli alunni. Secondo quanto spiegato in un intervento video, la misurazione didattica deve certamente tutelare l'apprendimento delle competenze di base, ma al tempo stesso deve fungere da strumento attivo in grado di valorizzare le inclinazioni e i talenti personali di ciascuno studente, accompagnando con efficacia sia i giovani in difficoltà sia coloro che eccellono nel loro percorso di studi. Lo riferisce Orizzonte Scuola.",
   "more": [
    "I test standardizzati predisposti dall'Invalsi rilevano annualmente i livelli di competenza degli studenti italiani in italiano, matematica e inglese. Nel dibattito pedagogico si confrontano da tempo modelli valutativi incentrati sul mero controllo dei livelli minimi e approcci orientati alla valorizzazione formativa dei singoli percorsi educativi."
   ],
