   "id": "z1835d8a4",
   "sez": "salute",
   "titolo": "Uno studio evidenzia una marcata variabilità nell'attività cerebrale delle persone con autismo",
   "orig": "People with autism show remarkable variability in brain activity",
   "lead": "Una ricerca scientifica guidata da Dorit Kliemann e James Traer dell'Università dell'Iowa ha messo a confronto l'attività cerebrale tra individui con disturbo dello spettro autistico e soggetti neurotipici. Pubblicato sulla rivista specializzata JNeurosci, il lavoro collaborativo evidenzia come le persone con autismo presentino una notevole e singolare variabilità nei pattern neurali rispetto al gruppo di controllo. La scoperta offre elementi inediti per approfondire i meccanismi biologici del funzionamento cerebrale e comprendere meglio le differenze individuali che caratterizzano questa complessa condizione dello sviluppo neurologico. Lo riferisce Medical Xpress.",
   "more": [
    "Il disturbo dello spettro autistico raccoglie una vasta gamma di caratteristiche relative alla comunicazione, all'interazione sociale e alla sensibilità sensoriale. L'impiego delle tecniche di neuroimaging consente ai ricercatori di analizzare i flussi di informazione tra le varie aree cerebrali, delineando le basi fisiologiche della neurodivergenza."
   ],
