   "sez": "sport",
   "titolo": "Il centrocampista Daniel-Kofi Kyereh torna nella nazionale ghanese dopo quattro anni di infortunio",
   "orig": "Black Stars return a ‘dream come true’ – Kofi Kyereh",
   "lead": "Il calciatore ghanese Daniel-Kofi Kyereh ha definito il proprio rientro nella nazionale delle Black Stars come un sogno divenuto finalmente realtà. Il centrocampista era rimasto a lungo lontano dai campi di gioco internazionali a causa di un grave infortunio che lo ha costretto a uno stop durato quattro anni. Dopo il lungo percorso di recupero fisico e il ritorno all'attività agonistica, la convocazione e la presenza con la rappresentativa del Ghana rappresentano un importante traguardo personale per la prosecuzione della sua carriera calcistica. Lo riferisce MyJoyOnline.",
   "more": [
    "Le Black Stars, nome con cui è nota la nazionale di calcio del Ghana, sono una delle formazioni più titolate e seguite del continente africano. Gli infortuni articolari di lunga durata richiedono complessi protocolli di riabilitazione prima che un atleta professionista possa ritrovare il ritmo delle competizioni internazionali."
   ],
