   "titolo": "Nel cricket Towhid Hridoy guida la rimonta del Bangladesh con un century contro il Sudafrica",
   "orig": "Towhid Hridoy century puts Bangladesh back on track against South Africa",
   "lead": "Il battitore emergente Towhid Hridoy ha firmato un secolo fondamentale nella sfida di cricket che vede contrapposto il Bangladesh alla nazionale del Sudafrica. Dopo un avvio travolgente dell'attacco sudafricano guidato dal lanciatore Kagiso Rabada, la prestazione solida e determinata di Hridoy ha permesso alla formazione asiatica di rimettersi in carreggiata. Grazie a una collaborazione da record con i compagni di squadra, il giocatore ha guidato la reazione del Bangladesh nella fase critica del Test match, contrastando l'offensiva dei padroni di casa sudafricani.",
   "more": [
    "Nel cricket un 'century' indica il traguardo individuale di cento corse realizzate in un singolo turno di battuta, un risultato tecnico di alto valore. Nei Test match, la forma più lunga e strategica di questo sport, una prestazione del genere può ribaltare l'inerzia di una partita."
   ],
