   "id": "z0f00a662",
   "sez": "economia",
   "titolo": "L'economia tedesca torna a crescere leggermente, ma gli economisti restano preoccupati",
   "orig": "German economy returns to growth, so why is the country still worried?",
   "lead": "I dati congiunturali indicano che l'economia della Germania è tornata a registrare un incremento, seppure modesto, uscendo dalla stagnazione. Nonostante questo segnale positivo, tra gli analisti ed economisti permane una forte preoccupazione per le prospettive a lungo termine del Paese. Gli esperti avvertono infatti che, in assenza di profonde riforme strutturali, di una maggiore produttività del lavoro e di finanze pubbliche solide, le future generazioni rischiano di dover affrontare un calo sensibile del benessere economico e un progressivo aggravio dell'indebitamento statale. Lo riferisce Deutsche Welle.",
   "more": [
    "La Germania, principale potenza industriale europea, deve far fronte ai costi energetici elevati, all'invecchiamento demografico e alla transizione verso nuove tecnologie manifatturiere. Il modello export-dipendente tedesco richiede investimenti cospicui nell'innovazione per mantenere la propria competitività rispetto ai mercati internazionali."
   ],
