   "id": "za5e8ce2e",
   "sez": "ambiente",
   "titolo": "Le comunità locali denunciano l'esclusione dai fondi e dalle decisioni delle conferenze climatiche",
   "orig": "False benevolence of climate justice — billions for COP, crumbs for communities",
   "lead": "Un'analisi critica sul sistema della giustizia climatica evidenzia una forte sproporzione tra i miliardi mobilitati per i vertici internazionali come la COP e i reali benefici economici destinati alle comunità locali. Il settore dei negoziati globali viene accusato di replicare le disuguaglianze storiche, relegando i residenti dei territori più vulnerabili al ruolo di spettatori. A mancare, secondo le denunce, sono sia l'accesso a un effettivo potere decisionale sia una congrua ricaduta finanziaria diretta verso chi subisce in prima linea le conseguenze della crisi ecologica. Lo riferisce Daily Maverick.",
   "more": [
    "I vertici climatici delle Nazioni Unite riuniscono ogni anno governi, scienziati e organizzazioni per negoziare impegni sulle emissioni e creare fondi per i Paesi in via di sviluppo. Tuttavia, le popolazioni indigene e i territori marginalizzati lamentano spesso l'eccessiva burocratizzazione che impedisce l'arrivo diretto delle risorse economiche promesse."
   ],
