   "id": "z70d9c038",
   "sez": "adolescenti",
   "titolo": "Docenti derisi nei video sui social network: quali strumenti legali esistono per tutelarsi",
   "orig": "Video del docente pubblicato per deriderlo: quali strumenti di tutela ha l’insegnante? Il Punto di De Martino",
   "lead": "La diffusione sui social network o nelle chat di gruppo di filmati registrati in classe con l'intento di ridicolizzare o danneggiare gli insegnanti è al centro di una disamina giuridica. L'analisi approfondisce gli strumenti normativi e disciplinari a disposizione del corpo docente per difendere la propria dignità professionale e personale da atti di cyberbullismo o denigrazione digitale. Il fenomeno mette in luce la necessità di chiarire i confini tra vita scolastica e uso dei dispositivi mobili da parte degli studenti tra i banchi. Lo riferisce Orizzonte Scuola.",
   "more": [
    "L'introduzione degli smartphone negli ambienti scolastici pone delicate questioni di rispetto della privacy e diritto all'immagine. La legislazione italiana tutela i pubblici ufficiali e i lavoratori attraverso norme contro la diffamazione, mentre i regolamenti d'istituto prevedono sanzioni disciplinari per le riprese non autorizzate durante le lezioni."
   ],
