   "id": "z478c5df1",
   "sez": "salute",
   "titolo": "Una ricerca svela come il gusto acido riesca a sopraffare gli altri sapori nel cervello",
   "orig": "How sourness overpowers other kinds of tastes",
   "lead": "Uno studio condotto da Stephen Roper e dal suo gruppo presso la Miller School of Medicine dell'Università di Miami ha chiarito i processi con cui il sapore acido prevale sulle altre percezioni gustative. Pubblicata su JNeurosci, la ricerca ha esaminato il passaggio dei segnali dalla lingua al cervello nei modelli animali esposti a una combinazione di gusti, come dolce e aspro. I dati raccolti spiegano in che modo le papille gustative trasmettono informazioni complesse, facendo luce sui meccanismi biologici che regolano l'elaborazione dei sapori nel sistema nervoso. Lo riferisce Medical Xpress.",
   "more": [
    "La percezione gustativa è affidata a recettori specializzati distribuiti sulle papille della lingua, capaci di riconoscere dolce, salato, amaro, acido e umami. L'acidità è associata alla presenza di ioni idrogeno e ha una funzione evolutiva primaria nel segnalare cibi deteriorati o immaturi."
   ],
