   "id": "zc9e91314",
   "sez": "mondo",
   "titolo": "La Generazione 2008 al debutto elettorale in Spagna tra crisi, social network e orientamenti politici",
   "orig": "Retrato de la Generación 08: los hijos de las crisis y de TikTok estrenan mayoría de edad y voto el 29-N",
   "lead": "I giovani spagnoli nati nel 2008 raggiungono la maggiore età e si apprestano a partecipare per la prima volta al voto del 29 novembre. Cresciuta a stretto contatto con le crisi economiche e la comunicazione digitale di piattaforme come TikTok, questa generazione mostra idee e timori sul futuro del proprio Paese. Il dibattito pubblico e le inchieste giornalistiche mettono a confronto le aspettative di questi neoelettori con le scelte dei partiti, evidenziando una solida tenuta del consenso giovanile per formazioni come Vox, nonostante le perplessità suscitate da alcune recenti decisioni politiche.",
   "more": [
    "L'ingresso dei neodiciottenni nel corpo elettorale rappresenta un elemento di grande interesse sociologico nei sistemi parlamentari europei. I canali social hanno trasformato la comunicazione politica, influenzando i linguaggi con cui partiti tradizionali e formazioni nazionaliste cercano di attrarre le nuove generazioni."
   ],
