   "id": "z176031ea",
   "sez": "cultura",
   "titolo": "Il maltempo riduce i visitatori del festival letterario sul crimine a De Haan in Belgio",
   "orig": "Minder bezoekers voor 2e editie Crime Festival in De Haan door slecht weer: bijna 10.000 in plaats van 15.000",
   "lead": "La seconda edizione del Crime Festival di De Haan si è chiusa con un calo significativo di presenze a causa delle pessime condizioni meteorologiche. L'evento letterario belga della durata di cinque giorni ha attirato poco meno di diecimila visitatori, contro i quindicimila registrati durante il debutto dello scorso anno. L'organizzatore della manifestazione, Sébastien Momerency, ha spiegato che la pioggia incessante ha condizionato pesantemente la partecipazione del pubblico, compromettendo l'afflusso agli appuntamenti all'aperto previsti per gli appassionati del genere giallo e noir. Lo riferisce VRT NWS.",
   "more": [
    "I festival tematici dedicati alla letteratura poliziesca e d'indagine rappresentano un veicolo promozionale importante per autori, case editrici e turismo culturale delle località ospitanti. Il successo di tali rassegne all'aperto rimane tuttavia fortemente vincolato alla variabilità climatica stagionale."
   ],
