   "id": "ze0ebd2fc",
   "sez": "ambiente",
   "titolo": "Diciannove orbettini scambiati per vipere velenose vengono messi in salvo da un contatore dell'acqua",
   "orig": "19 slow worms mistaken for vipers rescued from water meter chamber",
   "lead": "Un insolito intervento di soccorso è stato portato a termine da un centro di recupero della fauna selvatica dopo una segnalazione che denunciava la presenza di serpenti velenosi in un pozzetto. I presunti rettili pericolosi rintracciati all'interno della camera di un contatore dell'acqua si sono rivelati essere diciannove innocui orbettini. Gli animali, privi di veleno e del tutto inoffensivi per l'uomo, avevano trovato rifugio nella cavità umida prima di essere identificati correttamente dagli operatori e trasferiti in sicurezza in un habitat idoneo. Lo riferisce Euronews.",
   "more": [
    "L'orbettino è un rettile appartenente all'ordine dei sauri, comunemente scambiato per un serpente a causa della totale assenza di zampe dovuta all'evoluzione. A differenza dei veri serpenti, possiede palpebre mobili ed è un prezioso alleato dell'ecosistema nutrendosi di lumache e insetti."
   ],
