   "sez": "cultura",
   "titolo": "Sint Eustatius commemora i duecentocinquant'anni dal riconoscimento dell'indipendenza degli Stati Uniti",
   "orig": "Sint Eustatius herdenkt 250 jaar First Salute. &#8216;Eindelijk durven Statianen te zeggen: wij zijn geen fragment in de Amerikaanse geschiedenis, we zijn een sleutelspeler'",
   "lead": "L'isola caraibica di Sint Eustatius celebra il 250º anniversario del First Salute con la visita ufficiale di re Guglielmo Alessandro dei Paesi Bassi. L'evento storico risale al 1776, anno in cui l'isola fu la prima entità territoriale estera a riconoscere formalmente l'indipendenza degli Stati Uniti d'America. Durante le celebrazioni per lo Statia Day, la popolazione e le istituzioni locali hanno rivendicato il proprio ruolo centrale nella storia internazionale, riflettendo contestualmente sul legame profondo e doloroso che unisce le lotte di indipendenza dell'epoca al passato della schiavitù coloniale. Lo riferisce NRC.",
   "more": [
    "Sint Eustatius, municipalità speciale dei Paesi Bassi nelle Antille, fu nel Settecento un porto franco cruciale per il commercio marittimo transatlantico. Il saluto con colpi di cannone alla bandiera della marina americana nel 1776 sancì il riconoscimento formale della nuova repubblica."
   ],
