   "sez": "economia",
   "titolo": "La corsa agli acquisti del Black Friday tra caccia agli sconti e attenzione alle spese responsabili",
   "orig": "Tra sconti e consigli per acquisti responsabili, una mappa per muoversi nel Black Friday",
   "lead": "In vista dell'imminente appuntamento con il Black Friday si intensifica la corsa agli acquisti da parte dei consumatori, spinti dalla ricerca di sconti convenienti anche in previsione dei regali di Natale. Le associazioni dei consumatori e l'Osservatorio Nazionale Federconsumatori monitorano le stime di spesa e offrono una guida per orientarsi tra le promozioni commerciali, raccomandando comportamenti responsabili per evitare ribassi ingannevoli e acquisti compulsivi. Gli operatori si preparano a gestire un periodo chiave per i bilanci della distribuzione commerciale sia nei negozi fisici sia sulle piattaforme online. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "Nato negli Stati Uniti all'indomani della festività del Ringraziamento, il Black Friday segna l'inizio ufficiale delle vendite natalizie a livello internazionale. Negli ultimi anni la ricorrenza si è estesa a un'intera settimana promozionale, con un impatto economico significativo sul commercio elettronico."
   ],
