   "titolo": "Pakistan: denunciati otto cittadini rimpatriati dalla Turchia per violazione delle norme sull'immigrazione",
   "orig": "FIA books 8 Pakistanis deported from Turkiye for violating immigration laws",
   "lead": "L'agenzia federale investigativa pachistana ha registrato una denuncia contro otto cittadini rimpatriati dalla Turchia per presunta violazione delle norme sull'immigrazione. Secondo le ricostruzioni fornite dalle autorità di Islamabad, gli individui avevano raggiunto il territorio turco con un regolare visto di lavoro, ma avrebbero successivamente prestato attività lavorativa illegale altrove anziché impiegarsi presso le aziende indicate nei documenti. Dopo essere stati arrestati e incarcerati dalle forze dell'ordine turche, gli otto sono stati espulsi verso il Pakistan, dove ora affrontano procedimenti legali. Lo riferisce Dawn.",
   "more": [
    "Le violazioni dei visti lavorativi comportano spesso espulsioni immediate e sanzioni nei Paesi d'origine per scoraggiare l'immigrazione irregolare. Accordi bilaterali tra governi regolano il rimpatrio di lavoratori che non rispettano i termini di soggiorno, per arginare il lavoro nero e tutelare la cooperazione sui flussi migratori."
   ],
