   "id": "ze676a20d",
   "sez": "tech",
   "titolo": "Stati Uniti: il dibattito sui data center e l'avanzata delle grandi società tecnologiche",
   "orig": "BUSINESS REFLECTION: Crossed Wires: The data centres are not the problem — it’s the tenants",
   "lead": "Negli Stati Uniti cresce la contestazione locale contro la proliferazione dei data center, strutture essenziali per sostenere le piattaforme digitali. Secondo un'analisi del settore, i divieti territoriali imposti dalle singole comunità non appaiono in grado di frenare l'espansione dell'intelligenza artificiale né di contenere il potere delle grandi aziende tecnologiche. La riflessione evidenzia come la questione principale non risieda nelle infrastrutture fisiche in sé, bensì nei modelli operativi e nelle esigenze dei colossi digitali che occupano tali centri, trainando consumi e trasformazioni su vasta scala. Lo riferisce Daily Maverick.",
   "more": [
    "I data center sono complessi che ospitano server e sistemi di archiviazione per gestire ed elaborare enormi volumi di dati. La diffusione dell'intelligenza artificiale ha generato un forte aumento del loro fabbisogno energetico e idrico, scatenando resistenze nelle comunità vicine per l'impatto ambientale e territoriale."
   ],
