   "id": "ze83b7c81",
   "sez": "tech",
   "titolo": "Roma: hacker quindicenni rubavano dati personali e diffondevano istruzioni su bombe e violazioni informatiche",
   "orig": "Hacker 15enni rubavano identità digitali e dati sensibili",
   "lead": "Un'indagine ha svelato le attività illecite condotte da un gruppo di quindicenni dediti al furto di identità digitali e di informazioni sensibili attraverso attacchi informatici. I giovani hacker non si limitavano a penetrare i sistemi protetti per sottrarre dati personali, ma producevano e diffondevano online tutorial dettagliati che spiegavano come eludere le misure di sicurezza cibernetica. Tra i contenuti realizzati e condivisi figuravano anche istruzioni pratiche destinate alla fabbricazione di ordigni esplosivi artigianali. Lo riferisce ANSA.",
   "more": [
    "Il fenomeno della criminalità informatica minorile è in ascesa grazie alla disponibilità di software malevoli e canali di messaggistica criptata. Spesso adolescenti esperti di tecnologia utilizzano piattaforme clandestine per condividere nozioni pericolose senza comprendere appieno la gravità delle conseguenze penali previste dalla legge."
   ],
