   "sez": "mondo",
   "titolo": "Kenya: il presidente Ruto respinge le accuse della Banca Mondiale sulla corruzione e punta il dito sul predecessore",
   "orig": "President Ruto blames Uhuru for World Bank's alarm on graft",
   "lead": "Il presidente del Kenya William Ruto ha attribuito all'amministrazione dell'ex capo di Stato Uhuru Kenyatta le responsabilità legate all'allarme lanciato dalla Banca Mondiale sui casi di corruzione nel Paese. Durante il suo intervento, il leader keniota ha respinto con fermezza ogni tentativo di collegare la sua persona alle presunte irregolarità relative al progetto ferroviario Standard Gauge Railway. Ruto ha inoltre dichiarato che alcuni dei suoi contestatori potrebbero avere interessi economici diretti nelle ingenti risorse finanziarie impiegate per la realizzazione dell'infrastruttura. Lo riferisce Citizen Digital.",
   "more": [
    "La ferrovia Standard Gauge Railway è una delle maggiori opere infrastrutturali realizzate in Kenya negli ultimi anni per collegare il porto di Mombasa all'entroterra. Il progetto, finanziato largamente con prestiti esteri, è stato al centro di intense polemiche politiche per i costi e la trasparenza contrattuale."
   ],
