   "titolo": "Filippine: al vertice Apec in Cina il presidente Marcos cerca l'equilibrio tra investimenti e geopolitica",
   "orig": "Marcos faces balancing act at Apec summit in China",
   "lead": "In vista del trentatreesimo incontro dei leader economici dell'Apec ospitato in Cina, il presidente delle Filippine Ferdinand Marcos Jr. è chiamato a bilanciare la diplomazia commerciale con le tensioni internazionali. Secondo gli analisti, la priorità dell'amministrazione di Manila dovrebbe concentrarsi su commercio, investimenti ed integrazione economica regionale, superando le controversie geopolitiche per difendere gli interessi nazionali. La Cina rappresenta la seconda economia mondiale per prodotto interno lordo nominale e la prima per parità di potere d'acquisto, costituendo un partner centrale nel consesso asiatico. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "L'Asia-Pacific Economic Cooperation (APEC) è un forum economico regionale nato per favorire il libero scambio e la cooperazione tra i Paesi dell'area pacifica. I rapporti tra Manila e Pechino restano complessi a causa di contese territoriali e marittime, pur mantenendo intensi scambi commerciali bilaterali."
   ],
