   "titolo": "Archeologia in Scozia: l'arto in bronzo del 1820 potrebbe appartenere all'imperatore Antonino Pio",
   "orig": "Ritrovata in Scozia una gamba in bronzo che potrebbe appartenere all’imperatore romano Antonino Pio",
   "lead": "Una nuova ipotesi archeologica suggerisce che una gamba in bronzo dorato, rinvenuta originariamente nel 1820 in territorio scozzese, potrebbe appartenere a una statua raffigurante l'imperatore romano Antonino Pio. Secondo le recenti analisi storiche, la manifattura e la collocazione del reperto sarebbero direttamente collegate alla presenza dell'esercito romano durante le fasi di costruzione e presidio del Vallo Antonino. L'opera costituirebbe una testimonianza rilevante delle raffigurazioni imperiali erette nelle province di frontiera dell'antico impero. Lo riferisce Geopop.",
   "more": [
    "Il Vallo Antonino è una fortificazione in pietra e terra costruita dai Romani in Scozia attorno al 142 d.C., su ordine dell'imperatore Antonino Pio, a nord del Vallo di Adriano. Le sculture monumentali dei governanti servivano a manifestare l'autorità imperiale lungo i confini dell'impero."
   ],
