   "sez": "economia",
   "titolo": "Filippine: gli economisti chiedono alla banca centrale di mantenere tassi elevati contro l'inflazione",
   "orig": "BSP urged to stay hawkish despite anemic GDP growth",
   "lead": "La Bank of the Philippine Islands ha invitato la banca centrale nazionale a proseguire con una linea rigorosa di politica monetaria, nonostante i deboli dati relativi alla crescita del prodotto interno lordo. Emilio Neri Jr., capo economista dell'istituto finanziario, ha avvertito che un arresto prematuro dei rialzi dei toni di interesse rischierebbe di alimentare nuovamente l'inflazione, aggravando le difficoltà di bilancio delle famiglie. Secondo l'istituto privato, la responsabilità di contrastare il carovita non deve ricadere unicamente sulle spalle dell'autorità di regolamentazione monetaria. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "La politica monetaria hawkish, o restrittiva, consiste nell'aumento o nel mantenimento di tassi d'interesse elevati per raffreddare la domanda e contenere la crescita dei prezzi al consumo. Un rallentamento della crescita economica rende tuttavia complessa la scelta delle banche centrali tra sostegno al PIL e stabilità monetaria."
   ],
