   "titolo": "Filippine: la borsa propone un tetto uniforme del 10% alle oscillazioni di prezzo per tutti i titoli",
   "orig": "PSE pushes single 10% dynamic threshold for all securities",
   "lead": "La borsa valori delle Filippine ha proposto l'introduzione di una soglia dinamica uniforme del dieci per cento per tutti gli strumenti finanziari quotati. La misura mira a rendere più rigidi i limiti sulle variazioni di prezzo tra una negoziazione e l'altra, tutelando soprattutto i titoli scambiati con minore frequenza all'interno del listino. In base alla proposta, la differenza massima di prezzo consentita tra gli aggiornamenti consecutivi durante le contrattazioni continue verrebbe vincolata al tetto prefissato, a prescindere dal volume e dalla frequenza delle transazioni registrate sul mercato. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "I circuit breaker e le soglie di oscillazione sono meccanismi di salvaguardia adottati dalle borse per prevenire scostamenti anomali dovuti a speculazione o panico. Fissare una soglia uniforme tutela i mercati meno liquidi, dove scambi ridotti possono provocare variazioni percentuali eccessive."
   ],
