   "titolo": "Filippine: i nuovi pozzi del giacimento di Malampaya potrebbero fruttare 500 milioni di dollari allo Stato",
   "orig": "New Malampaya natural gas wells could yield $500M",
   "lead": "La società Prime Energy Resources Development, parte del gruppo Razon, ha comunicato che le recenti trivellazioni effettuate nel giacimento di gas naturale di Malampaya consentiranno di versare allo Stato filippino circa mezzo miliardo di dollari in royalty aggiuntive. Sulla scorta dei test operativi condotti sui pozzi, l'azienda stima che tali introiti fiscali per le casse pubbliche verranno generati nell'arco dei sei anni di estensione delle attività. Il progetto rappresenta una componente strategica per le riserve energetiche interne dell'arcipelago. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "Il giacimento sottomarino di Malampaya, situato al largo dell'isola di Palawan, è una delle principali fonti energetiche delle Filippine, fornendo gas naturale per alimentare le centrali elettriche dell'isola di Luzon e sostenere il fabbisogno industriale nazionale."
   ],
