   "titolo": "Economia e intelligenza artificiale: il dibattito sulla gestione dei rischi negli investimenti",
   "orig": "Opinion | What Happens When the Economy Becomes Dependent on AI?",
   "lead": "La progressiva diffusione dell'intelligenza artificiale nei settori chiave dell'economia mondiale impone una gestione sempre più rigorosa dei rischi sistemici. Secondo un'analisi del Daily News Egypt, gli algoritmi guidano ormai decisioni cruciali in ambiti quali l'erogazione del credito, le strategie d'investimento, i mercati finanziari, la produzione e la manutenzione delle infrastrutture. Il confronto internazionale sul tema non riguarda più soltanto la capacità dei software di redigere testi o analizzare dati, ma si focalizza sull'impatto economico complessivo e sulle vulnerabilità derivanti dalla dipendenza delle istituzioni finanziarie dai modelli automatizzati.",
   "more": [
    "L'integrazione di sistemi di intelligenza artificiale nei servizi finanziari accelera l'elaborazione delle transazioni e la profilazione del rischio creditizio. Tuttavia, l'assenza di trasparenza nei processi decisionali degli algoritmi solleva interrogativi di stabilità per le autorità di vigilanza macroeconomica."
   ],
