   "sez": "economia",
   "titolo": "Bessent: l'Iran affronta uno dei collassi economici più rapidi della storia",
   "orig": "Bessent Says Iran Faces One of History’s Fastest Economic Collapses",
   "lead": "Secondo Scott Bessent, l'Iran sta affrontando uno dei crolli economici più rapidi della storia recente. Parlando durante alcune interviste rilasciate alle emittenti Fox News e Iran International, Bessent ha spiegato che le misure statunitensi dirette a colpire i canali finanziari, marittimi e commerciali terrestri di Teheran stanno limitando in modo sempre più marcato la capacità della Repubblica Islamica di generare entrate economiche e risorse valutarie indispensabili per il proprio bilancio statale. Lo riferisce Kurdistan24.",
   "more": [
    "Le sanzioni economiche imposte dagli Stati Uniti contro l'Iran mirano storicamente a colpire le esportazioni petrolifere, le transazioni bancarie internazionali e le reti di trasporto marittimo. Queste restrizioni puntano a ridurre i proventi statali e a isolare finanziariamente Teheran dai mercati globali, influenzando fortemente l'inflazione e la stabilità monetaria interna."
   ],
