   "id": "z9e1dfdf0",
   "sez": "economia",
   "titolo": "Kontigo sospende le operazioni in bolívares dopo l'intervento della vigilanza bancaria venezuelana",
   "orig": "Kontigo atribuyó la suspensión de operaciones en bolívares a un procedimiento administrativo contra OHA Technology",
   "lead": "L'applicazione finanziaria Kontigo ha attribuito l'interruzione delle proprie operazioni in bolívares a un procedimento amministrativo aperto contro la società venezuelana OHA Technology. Il blocco è scattato in seguito a una direttiva con cui la Sudeban, l'autorità di vigilanza bancaria del Venezuela, ha imposto al sistema bancario nazionale di sospendere i rapporti con l'azienda. Kontigo ha comunque assicurato che i fondi restano sotto l'esclusivo controllo dei clienti, rendendo disponibili i prelievi senza l'applicazione di commissioni. Lo riferisce El Nacional.",
   "more": [
    "La Sudeban è la soprintendenza del settore bancario in Venezuela, responsabile della regolamentazione, vigilanza e controllo delle istituzioni finanziarie pubbliche e private. In contesti di forte volatilità valutaria, le autorità monetarie intervengono frequentemente per monitorare le transazioni elettroniche e prevenire irregolarità nei flussi in valuta locale ed estera."
   ],
