   "sez": "economia",
   "titolo": "Banca centrale del Paraguay: priorità al recupero rapido di fiducia e reputazione",
   "orig": "Jorge Schreiner: “Prioridad que el Banco Central recupere lo más rápido posible su credibilidad y reputación nacional e internacional”",
   "lead": "La priorità del nuovo direttivo del Banco Central del Paraguay è recuperare con la massima urgenza la fiducia, la credibilità e la reputazione dell'istituto a livello nazionale e internazionale. A dichiararlo è stato Jorge Schreiner, sottolineando gli obiettivi immediati della dirigenza della banca centrale paraguaiana. Il nuovo vertice considera essenziale ristabilire la credibilità operativa e l'autorevolezza dell'organismo monetario nei confronti dei mercati e dell'opinione pubblica dopo le recenti difficoltà istituzionali. Lo riferisce ABC Color.",
   "more": [
    "Le banche centrali svolgono un ruolo fondamentale nel garantire la stabilità monetaria, il controllo dell'inflazione e la supervisione del sistema finanziario di uno Stato. La credibilità e l'indipendenza delle loro decisioni rappresentano pilastri cruciali per rassicurare gli investitori internazionali e preservare la tenuta del sistema bancario nazionale."
   ],
