   "titolo": "La Chiesa cattolica paraguaiana attacca Ueno Bank durante l'omelia nella Cattedrale",
   "orig": "Ueno Bank: “Basta de burlarse y de explotar al pueblo paraguayo”, exige la Iglesia",
   "lead": "Durante l'omelia per la messa dei 450 anni di San Rocco nella Cattedrale Metropolitana, il cardinale Adalberto Martínez ha espresso una dura presa di posizione contro Ueno Bank, chiedendo di cessare ogni forma di sfruttamento e presa in giro nei confronti del popolo paraguaiano. L'intervento della Chiesa cattolica paraguaiana riflette il crescente malcontento sociale verso l'istituto di credito, sollecitando maggiore rispetto e tutela per i cittadini e per gli utenti dei servizi finanziari. Lo riferisce ABC Color.",
   "more": [
    "In diversi Paesi dell'America Latina, le gerarchie della Chiesa cattolica esercitano un ruolo di influenza morale e critica sociale, intervenendo pubblicamente su questioni economiche, disuguaglianze e protezione dei consumatori più vulnerabili di fronte alle pratiche del settore creditizio e bancario commerciale."
   ],
