   "titolo": "Sri Lanka, la realtà sociale contrasta con lo status di reddito medio-alto della Banca Mondiale",
   "orig": "Sri Lanka reality contrasts with new World Bank upper-middle-income status",
   "lead": "Le reali condizioni economiche della popolazione dello Sri Lanka mostrano un forte contrasto con il recente status di reddito medio-alto assegnato al Paese dalla Banca Mondiale. Nonostante i parametri statistici dell'istituzione internazionale certifichino una ripresa formale e un miglioramento degli indicatori macroeconomici, la quotidianità delle famiglie e dei lavoratori sull'isola continua a fare i conti con pesanti difficoltà sociali, carovita e disuguaglianze ereditate dalla gravissima crisi finanziaria degli ultimi anni. Lo riferisce Nikkei Asia.",
   "more": [
    "La Banca Mondiale classifica le economie mondiali in fasce di reddito basandosi sul reddito nazionale lordo pro capite calcolato in dollari. Questa classificazione statistica può tuttavia non riflettere la reale distribuzione della ricchezza, la povertà diffusa, l'indebitamento delle famiglie e il potere d'acquisto effettivo all'interno di un'economia nazionale."
   ],
