   "id": "z2641a633",
   "sez": "economia",
   "titolo": "Cresce dell'81 percento il valore delle vendite sulla Borsa dell'Energia iraniana",
   "orig": "Iran Energy Exchange sales value expands 81%",
   "lead": "Il valore complessivo delle vendite registrate sulla Borsa dell'Energia dell'Iran ha messo a segno una crescita dell'81 percento. L'incremento del volume dei contratti negoziati riflette una vivace attività nelle transazioni energetiche interne e nelle vendite transfrontaliere intermediate dalla piattaforma specializzata di Teheran. L'espansione del mercato commerciale dell'energia avviene in un contesto in cui il Paese cerca di massimizzare la valorizzazione delle proprie risorse e di diversificare i canali di scambio dei prodotti petroliferi ed elettrici. Lo riferisce Trend.",
   "more": [
    "La Borsa dell'Energia iraniana opera come piattaforma per la compravendita di elettricità, petrolio, prodotti petrolchimici e derivati del gas. Tali mercati telematici consentono alle aziende e agli intermediari di scambiare carichi energetici attraverso contratti all'ingrosso, favorendo la trasparenza dei prezzi e la liquidità nel commercio energetico regionale."
   ],
