   "id": "z1bf6f4e1",
   "sez": "dibattito",
   "titolo": "Nel Regno Unito si valuta un'età del consenso scaglionata dopo i casi nel mondo dello spettacolo",
   "orig": "Brand, Walliams and MAFS: Is this a reckoning for the entertainment industry?",
   "lead": "Nel Regno Unito si discute l'introduzione di un'età del consenso scaglionata in base alla differenza anagrafica tra le parti. L'ipotesi, che i ministri britannici hanno annunciato di voler valutare, nasce a seguito delle rivelazioni che hanno coinvolto figure del mondo dello spettacolo come Russell Brand e David Walliams. La proposta punta a vietare legalmente agli uomini adulti oltre una certa età di avere rapporti sessuali con giovani di sedici e diciassette anni. L'obiettivo del confronto è rafforzare la tutela legale delle adolescenti prevenendo relazioni segnate da asimmetrie di potere ed esperienze di abuso.",
   "more": [
    "Nel Regno Unito l'età legale del consenso sessuale è attualmente fissata a sedici anni, senza restrizioni generali sull'età del partner adulto. Il modello a età scaglionata prevede che i minori di una specifica fascia anagrafica possano intrattenere rapporti solo con coetanei o con partner che non superino un determinato divario d'età, per evitare disparità e condotte manipolatorie."
   ],
