   "sez": "mondo",
   "titolo": "La Moldavia vieta l'espatrio al leader separatista della Transnistria Vadim Krasnoselski",
   "orig": "Update: Separatist leader Vadim Krasnoselski barred from leaving Moldova after returning from Moscow",
   "lead": "Il leader separatista della Transnistria, Vadim Krasnoselski, è stato sottoposto al divieto di lasciare la Moldavia al suo rientro da un viaggio a Mosca. Il governo di Chișinău ha annunciato che, una volta concluse le verifiche di sicurezza in corso, Krasnoselski dovrà affrontare precise conseguenze legali collegate ai recenti episodi avvenuti nella capitale russa. La misura restrittiva imposta dalle autorità moldave accresce le tensioni istituzionali tra la presidenza centrale e l'amministrazione della regione secessionista filorussa situata lungo la riva orientale del fiume Nistro.",
   "more": [
    "La Transnistria è una regione secessionista che si è autoproclamata indipendente dalla Moldavia nel 1990, pur non godendo di riconoscimento da parte della comunità internazionale. Il territorio mantiene stretti legami politici, economici e militari con la Russia, che vi stanzia un contingente di truppe, rappresentando un fattore costante di attrito per la sicurezza di Chișinău."
   ],
