   "titolo": "Circa quindicimila migranti restano a Ceuta mentre la Spagna riprende i rimpatri in Marocco",
   "orig": "3 months after mass entry, some 15,000 migrants remain in Ceuta",
   "lead": "Circa quindicimila migranti rimangono bloccati nell'enclave spagnola di Ceuta a tre mesi dal loro ingresso di massa dal Marocco. Molti di loro sperano ancora che il territorio nordafricano consenta un trasferimento verso la Spagna continentale e l'Europa, mentre i residenti e le istituzioni locali faticano a gestire l'ondata. Nel frattempo, le autorità di Madrid hanno ripreso a rimpatriare centinaia di cittadini marocchini trattenuti nel centro di Algeciras, consegnandoli direttamente alla frontiera di Tarajal dopo anni di sospensione delle procedure concordate tra i due governi.",
   "more": [
    "Ceuta e Melilla sono due città autonome spagnole situate sulla costa settentrionale del Marocco e rappresentano gli unici confini terrestri dell'Unione Europea nel continente africano. La gestione dei flussi migratori lungo queste frontiere è regolata da accordi bilaterali tra Madrid e Rabat per i controlli congiunti e le riammissioni."
   ],
