   "id": "z508ebb36",
   "sez": "sport",
   "titolo": "Nations Championship di rugby: la Scozia batte l'Australia, sconfitte le Figi contro l'Irlanda",
   "orig": "Nations Championship: Fiji remain winless after Irish loss",
   "lead": "Nella quinta giornata del Nations Championship di rugby, le Figi sono rimaste a secco di vittorie dopo essere state superate dall'Irlanda, con la frustrazione del nuovo commissario tecnico Jack White visibile in tribuna durante il match. A Edimburgo, la Scozia è riuscita a resistere alla rimonta dell'Australia imponendosi allo stadio di Murrayfield con il punteggio finale di 15-12. Il successo della nazionale scozzese è stato firmato dalle mete realizzate da Matt Fagerson e Jack Dempsey, che hanno assicurato un'affermazione di prestigio contro i Wallabies.",
   "more": [
    "Il rugby internazionale ai massimi livelli vede storicamente contrapposte le migliori selezioni dell'emisfero boreale e di quello australe. Competizioni e test match autunnali mettono a confronto squadre con tradizioni e stili differenti, assegnando punti rilevanti per il ranking mondiale stilato dalla federazione internazionale World Rugby."
   ],
