   "sez": "mondo",
   "titolo": "Kirghizistan, il presidente Japarov mette in guardia dal rischio di disordini etnici prima del voto",
   "orig": "Japarov Warns of Ethnic Unrest Ahead of Kyrgyzstan’s Presidential Election",
   "lead": "In vista delle prossime elezioni presidenziali in Kirghizistan, il presidente Sadyr Japarov ha lanciato un duro allarme sulla possibilità di disordini etnici nel Paese. Il capo dello Stato ha denunciato che alcuni politici starebbero pianificando manovre per incitare alla violenza e provocare tensioni tra la maggioranza etnica kirghisa e le altre comunità residenti sul territorio nazionale. Le dichiarazioni di Japarov intendono richiamare l'attenzione sul pericolo di strumentalizzazioni della convivenza interetnica a fini elettorali durante la campagna politica. Lo riferisce The Times of Central Asia.",
   "more": [
    "Il Kirghizistan ha vissuto in passato momenti di grave conflitto interetnico, in particolare nel sud del Paese dove convivono comunità kirghise e uzbeche. La stabilità interna e la sicurezza pubblica rimangono questioni di estrema sensibilità per il governo di Bishkek, soprattutto in concomitanza con importanti scadenze istituzionali ed elettorali."
   ],
