   "id": "z3e031877",
   "sez": "mondo",
   "titolo": "Elezioni in Gambia: Adama Barrow cerca il terzo mandato contro quattro rivali",
   "orig": "Adama Barrow brigue un troisième mandat face à quatre adversaires en Gambie",
   "lead": "In Gambia si prepara una nuova tornata per le elezioni presidenziali con cinque candidati complessivi in corsa per la guida dello Stato. Il presidente uscente Adama Barrow ha formalizzato la decisione di candidarsi per un terzo mandato presidenziale, sfidando quattro avversari che mirano a strappargli il controllo dell'esecutivo. La competizione elettorale viene seguita con particolare attenzione nell'intera regione dell'Africa occidentale, in un contesto nazionale ancora profondamente influenzato dall'eredità politica e sociale degli anni del regime guidato da Yahya Jammeh. Lo riferisce France 24.",
   "more": [
    "Adama Barrow è salito per la prima volta al potere in Gambia nel 2016, ponendo fine al ventennale governo autoritario di Yahya Jammeh. Nonostante l'avvio di un percorso democratico, la scelta di ricandidarsi oltre il secondo mandato suscita un forte dibattito sui limiti costituzionali e sul consolidamento delle istituzioni repubblicane nel Paese."
   ],
