   "id": "zd595a9fd",
   "sez": "sport",
   "titolo": "Nations League: i tifosi italo-belgi di Genk a Bruxelles per sostenere l'Italia",
   "orig": "Italiaanse Genkenaren trekken naar Koning Boudewijnstadion om te supporteren voor 'hun' ploeg: \"Vanavond zijn we 100 % Italiaan\"",
   "lead": "In vista della sfida di Nations League tra Belgio e Italia allo stadio Re Baldovino di Bruxelles, i residenti di origine italiana della città di Genk si sono organizzati in pullman per sostenere gli azzurri. La partita rappresenta un passaggio decisivo per le sorti del girone, con i padroni di casa costretti a vincere per non mancare la qualificazione ai quarti di finale. La mobilitazione della storica comunità italo-belga testimonia il profondo legame culturale e sportivo che anima i tifosi divisi tra il Paese d'adozione e quello d'origine. Lo riferisce VRT NWS.",
   "more": [
    "La presenza di un'ampia comunità di origine italiana a Genk e nella provincia del Limburgo risale agli accordi bilaterali del dopoguerra per il lavoro nelle miniere di carbone. Nel tempo questa collettività ha mantenuto salde radici culturali, che emergono regolarmente in occasione degli incontri calcistici internazionali tra Belgio e Italia."
   ],
