   "id": "z92d6aa9e",
   "sez": "sport",
   "titolo": "Hockey su ghiaccio: la Russia esclusa dai Mondiali Juniores per le restrizioni del Canada",
   "orig": "Ice hockey-IIHF confirms Russia will miss World Juniors over Canada restrictions",
   "lead": "La Federazione Internazionale di Hockey su Ghiaccio ha confermato che la nazionale russa non prenderà parte ai prossimi Campionati Mondiali Juniores. L'esclusione della selezione giovanile è stata determinata dalle restrizioni adottate dalle autorità del Canada, Paese designato per ospitare la prestigiosa competizione internazionale. La decisione della federazione ratifica l'impossibilità di garantire la partecipazione degli atleti russi a causa delle disposizioni governative canadesi, prolungando il divieto di partecipazione per le squadre di Mosca nei tornei mondiali di categoria.",
   "more": [
    "Dall'inizio del conflitto in Ucraina nel 2022, la Federazione Internazionale di Hockey su Ghiaccio ha sospeso le squadre nazionali e i club di Russia e Bielorussia da tutte le competizioni ufficiali. A queste misure si sommano spesso i dinieghi sui visti d'ingresso imposti dai Paesi ospitanti per gli eventi sportivi."
   ],
