   "sez": "mondo",
   "titolo": "Manifestanti contestano le politiche Usa all'apertura del summit Asean a Manila",
   "orig": "Protesters condemn US policies as ASEAN summit begins in Manila",
   "lead": "Mentre si apre il summit dell'Asean nelle Filippine, i leader del sud-est asiatico in arrivo a Manila sono stati accolti da manifestazioni di protesta contro le politiche statunitensi. Al momento non sono stati riportati dettagli sulle richieste specifiche dei manifestanti né sulla risposta delle autorità filippine. Lo riferisce Al Jazeera.",
   "more": [
    "L'Asean è l'organizzazione che riunisce dieci paesi del sud-est asiatico per promuovere cooperazione economica e politica regionale. I summit periodici sono spesso occasione di tensioni legate al ruolo delle grandi potenze, Stati Uniti e Cina, nella regione."
   ],
