   "id": "z02299cd2",
   "sez": "italia",
   "titolo": "Crosetto: la guerra cognitiva è già qui, attenzione ai rischi",
   "orig": "Crosetto:guerra cognitiva è qui, rischi",
   "lead": "Il ministro della Difesa Guido Crosetto ha dichiarato che la cosiddetta \"guerra cognitiva\" è già una realtà presente, rivolgendosi anche alle opposizioni per richiamare l'attenzione sui rischi connessi. Lo riferisce Rai News.",
   "more": [
    "Con \"guerra cognitiva\" si intende l'uso di disinformazione, propaganda e manipolazione dell'opinione pubblica come strumento di conflitto, spesso attraverso i social media e le piattaforme digitali, parallelamente o in sostituzione dei conflitti armati tradizionali."
   ],
