   "titolo": "Usa, trovato ordigno vicino a un impianto di etanolo in Illinois: evacuazioni",
   "orig": "Bomb found near ethanol plant in central Illinois forces evacuations",
   "lead": "Un ordigno esplosivo è stato scoperto venerdì pomeriggio vicino all'impianto BioUrja Renewables a Peoria, in Illinois, costringendo le autorità a far evacuare l'area circostante. Le forze dell'ordine hanno definito la minaccia \"credibile\" e l'FBI ha avviato un'indagine. L'ordigno è stato successivamente neutralizzato in sicurezza. Lo riferiscono NPR e FBC News.",
   "more": [
    "Gli impianti industriali come le raffinerie di biocarburanti possono diventare obiettivo di minacce o atti dolosi; per questo le autorità statunitensi, in presenza di dispositivi sospetti, procedono abitualmente con l'evacuazione precauzionale dell'area e l'intervento di squadre artificieri specializzate."
   ],
