   "titolo": "Come osservare la parata planetaria di novembre nel cielo del mattino",
   "orig": "How to spot November's planetary parade in the pre-dawn sky",
   "lead": "Nel corso di novembre i pianeti Mercurio, Venere, Marte e Giove si allineano nel cielo poco prima dell'alba, offrendo l'occasione di osservare una cosiddetta parata planetaria. Lo riferisce la BBC, con indicazioni su come individuare i pianeti nel cielo pre-alba.",
   "more": [
    "Le parate planetarie si verificano quando più pianeti del sistema solare appaiono visibili contemporaneamente nel cielo notturno o all'alba dalla Terra, un fenomeno osservabile a occhio nudo o con un piccolo binocolo in condizioni di cielo sereno e scarso inquinamento luminoso."
   ],
