   "titolo": "\"Up on the Catwalk\": l'ultimo capolavoro new wave dei Simple Minds prima del successo mainstream",
   "orig": "Simple Minds - “Up On The Catwalk”, l’ultimo “glittering prize” dei Simple Minds",
   "lead": "OndaRock dedica un articolo a \"Up on the Catwalk\", il brano dei Simple Minds considerato l'ultimo grande episodio new wave della band scozzese prima del successo mondiale arrivato con \"Don't You (Forget About Me)\". Secondo la testata, il pezzo rappresenta il culmine artistico di una fase della carriera del gruppo, descritta come l'ultimo \"glittering prize\" prima della svolta verso un suono più pop e di largo consumo. Lo riferisce OndaRock.",
   "more": [
    "I Simple Minds, formatisi a Glasgow alla fine degli anni Settanta, sono passati da sonorità sperimentali e new wave a un pop-rock di stampo internazionale negli anni Ottanta, diventando una delle band più popolari del decennio grazie a brani come \"Don't You (Forget About Me)\", colonna sonora del film \"The Breakfast Club\"."
   ],
