   "id": "zc88c8136",
   "sez": "ambiente",
   "titolo": "Chi è ricco può sfuggire al cambiamento climatico, ma non alle proprie emissioni",
   "orig": "The rich find ways to escape climate change. Their emissions have not.",
   "lead": "Un'analisi del Financial Times evidenzia come un numero crescente di studi mostri forti differenze nelle emissioni di gas serra tra persone ricche e povere, differenze che si manifestano in modo marcato anche all'interno dello stesso paese e non solo tra nazioni diverse. Secondo la ricerca citata dal quotidiano britannico, i più ricchi riescono spesso a proteggersi meglio dagli effetti del cambiamento climatico, ma restano comunque i maggiori responsabili delle emissioni che lo causano. Lo riferisce Financial Times.",
   "more": [
    "Diversi studi internazionali indicano che una piccola percentuale della popolazione mondiale più ricca è responsabile di una quota sproporzionata delle emissioni globali di CO2, legate a consumi come viaggi aerei, grandi abitazioni e beni di lusso, mentre le fasce più povere, che inquinano meno, sono spesso le più esposte agli effetti climatici."
   ],
   "fonti": [
    {
     "n": "Financial Times",
     "p": "UK",
     "c": "Londra",
     "u": "https://www.ft.com/content/d42f1b8e-42ea-4018-8d1c-5d9c85a7fbc4?syn-25a6b1a6=1",
     "angolo": "",
     "atlas": "United Kingdom",
     "t": "2026-11-15T10:43+00:00"
    }
   ],
   "data": "15 nov",
