   "sez": "ingegneria",
   "titolo": "Un edificio commerciale rosa e \"non referenziale\" in Messico firmato Reims 502",
   "orig": "Reims 502 uses pink palette for \"non-referential\" commercial building in Mexico",
   "lead": "Lo studio messicano Reims 502 ha progettato Rosadoce, un edificio commerciale in Messico caratterizzato da una facciata a gradoni e una palette rosa, pensato per essere \"non referenziale\" e adattabile a diversi inquilini nel corso della sua vita utile. Il progetto punta a un linguaggio architettonico flessibile che possa ospitare attività commerciali differenti nel tempo senza legarsi a uno stile troppo specifico. Lo riferisce Dezeen.",
   "more": [
    "Negli ultimi anni diversi studi di architettura hanno privilegiato edifici commerciali con facciate flessibili e colori distintivi, per facilitare il riutilizzo degli spazi da parte di inquilini diversi nel tempo, riducendo la necessità di ristrutturazioni profonde a ogni cambio di destinazione d'uso."
   ],
