   "lead": "Il servizio di streaming RetroCrush ha annunciato l'aggiunta al proprio catalogo degli anime Sugar Sugar Rune e Genocyber, ampliando l'offerta dedicata ai titoli d'animazione giapponese più datati. Insieme ai due anime, il servizio ha aggiunto anche il film live-action del 1983 \"La ragazza che saltava nel tempo\". Lo riferisce Anime News Network.",
