   "sez": "organizzazioni",
   "titolo": "L'Aiea alla COP31 punta sul nucleare per la sicurezza energetica",
   "orig": "IAEA at COP31: Nuclear for Energy Security",
   "lead": "L'Agenzia internazionale per l'energia atomica (Aiea) ha presentato alla conferenza sul clima COP31 la propria posizione sull'energia nucleare come strumento per la sicurezza energetica globale. L'organizzazione ha sottolineato il ruolo che l'energia atomica può giocare nel garantire approvvigionamenti stabili ai paesi, in un contesto di transizione verso fonti a basse emissioni di carbonio. Lo riferisce l'Aiea.",
   "more": [
    "La COP31 è la conferenza delle Nazioni Unite sui cambiamenti climatici, sede in cui i paesi discutono impegni e politiche per ridurre le emissioni di gas serra; il nucleare viene presentato da alcuni governi e organizzazioni come fonte energetica a basse emissioni, pur restando oggetto di dibattito per i rischi legati a sicurezza e scorie radioattive."
   ],
