   "sez": "cultura",
   "titolo": "Una nuova generazione di attivisti per i diritti dei disabili raccoglie l'eredità di Judy Heumann",
   "orig": "A new generation of disability rights activists carry on Judy Heumann's legacy",
   "lead": "Il film \"Being Heumann\" racconta la storia meno conosciuta di Judy Heumann, considerata la madre del movimento per i diritti delle persone con disabilità negli Stati Uniti. Una nuova generazione di attivisti spiega, nel servizio di NPR, come stia portando avanti oggi il lavoro iniziato da Heumann, descrivendo il proprio impegno come un modo di \"portare la torcia\" ricevuta dalle generazioni precedenti del movimento. Lo riferisce NPR.",
   "more": [
    "Judy Heumann, scomparsa nel 2023, è stata una delle figure più importanti del movimento statunitense per i diritti delle persone con disabilità, protagonista di battaglie legali e politiche che hanno portato, tra l'altro, all'approvazione di leggi fondamentali per l'accessibilità e la non discriminazione negli Stati Uniti."
   ],
