   "id": "zeb082532",
   "sez": "economia",
   "titolo": "Il Bhutan riduce i tassi d'interesse sui prestiti per gli hotel a quattro stelle o meno",
   "orig": "Government reduces loan interest rates for four-star and lower-rated hotels",
   "lead": "Il governo del Bhutan ha approvato un piano di sostegno che riduce i tassi d'interesse sui prestiti bancari esistenti per gli hotel con classificazione a quattro stelle o inferiore. Secondo quanto riportato, un hotel che oggi paga un interesse del 12% vedrà il tasso scendere al 7%, riducendo le rate mensili. Per l'iniziativa il governo ha stanziato 844 milioni di ngultrum. Lo riferisce Bhutan Broadcasting Service.",
   "more": [
    "Il ngultrum è la valuta nazionale del Bhutan, agganciata alla rupia indiana. Misure di sostegno al settore turistico come la riduzione dei tassi sui prestiti mirano spesso ad alleggerire i costi finanziari delle strutture alberghiere più piccole, aiutandole a restare competitive sul mercato."
   ],
