   "sez": "adolescenti",
   "titolo": "Arrivava a cavallo per insegnare: la storia di una maestra argentina dopo 38 anni di scuola",
   "orig": "Arrivata a cavallo in un villaggio senza luce né telefono, ha insegnato 38 anni e ottenuto un ponte e una scuola nuova: la storia di una maestra",
   "lead": "Karina Guzmán ha insegnato per 38 anni a El Albardón, una piccola comunità rurale nel sud della provincia argentina di Santiago del Estero, dove è arrivata inizialmente a cavallo, in un villaggio senza luce né telefono. Ha iniziato con soli tre alunni in un ranch prestato e nel corso degli anni è riuscita a far costruire un ponte e una scuola nuova per la comunità. Lo riferisce Orizzonte Scuola.",
   "more": [
    "In molte aree rurali dell'America Latina l'accesso all'istruzione resta difficile per la mancanza di infrastrutture di base come strade, energia elettrica e collegamenti telefonici, rendendo il lavoro degli insegnanti nelle comunità isolate spesso determinante per la crescita educativa locale."
   ],
