   "id": "zcf851675",
   "sez": "mondo",
   "titolo": "Il governo del Tripura punta sullo sviluppo delle popolazioni tribali",
   "orig": "Tripura Government prioritising socio-economic development of tribals: CM Manik Saha",
   "lead": "Il capo del governo dello Stato indiano del Tripura, Manik Saha, ha dichiarato che l'esecutivo locale sta dando priorità allo sviluppo socio-economico delle popolazioni tribali. Lo ha affermato durante un evento per il 'Janjatiya Gaurav Diwas' a Chawmanu, nel distretto di Dhalai, ricordando il contributo dell'icona tribale Birsa Munda alla lotta per l'indipendenza dell'India. L'iniziativa si inserisce in una più ampia politica di valorizzazione delle comunità tribali nel Paese. Lo riferisce The Hindu.",
   "more": [
    "Birsa Munda è una figura storica venerata tra le comunità tribali indiane per la sua resistenza al colonialismo britannico nel XIX secolo. Il 'Janjatiya Gaurav Diwas' è una giornata istituita dal governo indiano per celebrare il contributo delle popolazioni tribali alla storia del Paese."
   ],
