   "sez": "economia",
   "titolo": "Nepal, le società idroelettriche potranno quotarsi al 50% dei lavori",
   "orig": "Hydropower firms to need 50 percent construction progress for IPOs",
   "lead": "In Nepal è stata proposta un'ordinanza che permetterebbe alle società idroelettriche di emettere azioni in borsa prima dell'avvio della produzione commerciale, a condizione che i progetti abbiano completato almeno la metà dei lavori fisici di costruzione. La misura mira a facilitare l'accesso al capitale per un settore chiave dell'economia nepalese, spesso frenato da difficoltà di finanziamento durante le fasi iniziali dei progetti. Lo riferisce The Kathmandu Post.",
   "more": [
    "L'energia idroelettrica rappresenta una delle principali risorse naturali e industrie del Nepal, Paese attraversato dalla catena himalayana e ricco di corsi d'acqua. Attrarre capitali privati fin dalle fasi di costruzione è considerato essenziale per sostenere lo sviluppo del settore."
   ],
