   "id": "z397289bd",
   "sez": "mondo",
   "titolo": "Il regime birmano cerca legami più stretti con il blocco economico guidato dalla Russia",
   "orig": "Myanmar Regime Seeks Closer Ties With Russian-Led Economic Bloc",
   "lead": "Una delegazione della Commissione economica eurasiatica ha visitato Naypyidaw, capitale del Myanmar, mentre la giunta militare sanzionata cerca di ottenere lo status di osservatore nel blocco economico guidato dalla Russia e punta a rafforzare scambi commerciali e investimenti. L'iniziativa si inserisce nel tentativo del regime birmano, isolato internazionalmente dopo il colpo di Stato, di trovare partner alternativi a Occidente e Stati Uniti. Lo riferisce The Irrawaddy.",
   "more": [
    "L'Unione economica eurasiatica è un blocco commerciale guidato dalla Russia che comprende diversi ex Stati sovietici. Il Myanmar, governato da una giunta militare dal colpo di Stato del 2021 e colpito da sanzioni occidentali, cerca da tempo nuovi partner economici tra Russia, Cina e altri Paesi disposti a ignorare le sanzioni."
   ],
