   "titolo": "Mozambico, il tribunale respinge il ricorso contro il monopolio statale sulle importazioni di cereali",
   "orig": "Just In: Administrative Tribunal rejects CIM’s bid to suspend Mozambique Grain Institute’s import mandate",
   "lead": "Il Tribunale amministrativo del Mozambico ha respinto la richiesta di sospensione cautelare presentata dall'azienda Companhia Industrial da Matola (CIM) contro il Diploma ministeriale n. 132/2025, che designa l'Istituto dei cereali del Mozambico (ICM) come ente statale incaricato di gestire le importazioni di riso e grano. Secondo il Tribunale non vi sarebbe un danno irreparabile per l'azienda. La decisione consente quindi all'ICM di proseguire nell'attuazione del nuovo mandato sulle importazioni. Lo riferisce Club of Mozambique.",
