   "id": "z291056f5",
   "sez": "sport",
   "titolo": "De la Fuente nega il razzismo in Spagna nonostante le denunce di Yamal e Vinicius",
   "orig": "De la Fuente denies racism in Spain despite Yamal, Vinicius avowals",
   "lead": "Il selezionatore della Spagna Luis de la Fuente ha negato l'esistenza di razzismo nel calcio spagnolo, nonostante le pubbliche denunce dei giocatori Lamine Yamal e Vinicius Jr, che hanno raccontato di aver subito abusi razzisti nel Paese. La Spagna ha già subito sanzioni dalla FIFA sulla questione e giocherà la prossima amichevole in casa con capienza ridotta per cori discriminatori contro i musulmani intonati dai tifosi. De la Fuente ha affrontato il tema con il selezionatore dell'Inghilterra Thomas Tuchel, che aveva annunciato di voler avvertire i suoi giocatori in vista della sfida tra le due nazionali.",
   "more": [
    "Il tema del razzismo negli stadi spagnoli è emerso più volte negli ultimi anni, con episodi di cori e insulti rivolti a giocatori di colore come Vinicius Jr, attaccante brasiliano del Real Madrid. La FIFA e la federazione spagnola hanno già adottato sanzioni, incluse restrizioni alla capienza degli stadi per cori discriminatori."
   ],
