   "titolo": "Arshdeep guida la rimonta dell'India, serie ODI vinta contro la Nuova Zelanda",
   "orig": "Arshdeep sparks India fightback to seal ODI series win over New Zealand",
   "lead": "L'India ha battuto la Nuova Zelanda nella quinta partita della serie ODI a Bay Oval, Mount Maunganui, grazie a una rimonta guidata dal bowler Arshdeep Singh, conquistando così la vittoria nella serie complessiva. La Nuova Zelanda, che doveva inseguire un punteggio di 210 runs, non è riuscita a completare la rimonta nel match decisivo. Lo riferisce CNA.",
