   "sez": "mondo",
   "titolo": "Due aerei si scontrano sulla pista dell'aeroporto di Miami",
   "orig": "Dois aviões colidem na pista do aeroporto internacional de Miami",
   "lead": "Due aerei si sono scontrati sabato sera sulla pista dell'aeroporto internazionale di Miami, causando due feriti leggeri. La punta dell'ala di un Boeing 737 della Copa Airlines ha urtato il muso di un Boeing 767 della UPS mentre entrambi gli aerei effettuavano manovre a terra vicino all'incrocio di due piste. Tutti i 166 passeggeri e i sei membri dell'equipaggio del volo Copa sono scesi senza problemi e l'aereo è tornato al terminal. L'incidente è avvenuto un giorno dopo la sospensione nazionale dei voli negli Stati Uniti legata a un guasto tecnico. Lo riferisce RTP.",
