   "id": "zcbd9938a",
   "sez": "cultura",
   "titolo": "Le ceneri del Nobel guatemalteco Miguel Ángel Asturias tornano in patria",
   "orig": "Guatemala: Trauerfeier für Literaturnobelpreisträger Asturias",
   "lead": "Le ceneri dello scrittore guatemalteco Miguel Ángel Asturias, premio Nobel per la letteratura nel 1967, sono tornate in Guatemala dopo 52 anni, accolte all'aeroporto La Aurora da scrittori, familiari e funzionari con rose bianche, al suono di strumenti tradizionali come il tum e la chirimilla, in occasione di una cerimonia funebre in suo onore. Asturias resta lo scrittore guatemalteco più riconosciuto a livello internazionale. Lo riferisce ORF.",
   "more": [
    "Miguel Ángel Asturias fu tra i cinque autori latinoamericani a vincere il Premio Nobel per la letteratura nel XX secolo, celebre per opere come 'Il signor Presidente', che denunciano le dittature in America Latina. Morì esule e le sue ceneri sono rimaste per decenni fuori dal Guatemala."
   ],
