   "id": "zf888e2a8",
   "sez": "italia",
   "titolo": "Falsi allarmi bomba provocano l'evacuazione di scuole in Italia, allarme anche in Regno Unito e Irlanda",
   "orig": "Bomb threat hoaxes prompt evacuation of Italian schools, alarm in UK and Ireland",
   "lead": "Centinaia di scuole in Italia sono state evacuate mercoledì dopo che minacce di bomba sono state inviate a circa 6.300 istituti scolastici, l'ultimo episodio di una serie di attacchi che hanno colpito infrastrutture in Europa. Anche scuole in Scozia, Irlanda del Nord e Repubblica d'Irlanda hanno ricevuto email simili lo stesso giorno, ma la polizia ha avvertito che si tratta probabilmente di falsi allarmi e che gli istituti non erano in pericolo reale. Lo riferisce Egypt Independent.",
   "more": [
    "Le minacce di bomba via email contro scuole o altre infrastrutture, spesso inviate in massa a migliaia di destinatari, sono un fenomeno diffuso in Europa negli ultimi anni: nella maggior parte dei casi si tratta di falsi allarmi, ma le autorità procedono comunque all'evacuazione precauzionale degli edifici coinvolti."
   ],
