   "titolo": "Egitto e 17 Paesi condannano l'attacco israeliano all'ospedale Nasser di Gaza",
   "orig": "Egypt and 17 countries condemn Israeli strike on Gaza’s Nasser hospital, urge US to enforce ceasefire",
   "lead": "In una dichiarazione congiunta, i ministri degli Esteri dei Paesi firmatari hanno affermato che l'attacco ha violato il diritto internazionale umanitario, che tutela in modo speciale le strutture sanitarie, e hanno chiesto agli Stati Uniti di far rispettare il cessate il fuoco in vigore. Lo riferisce Daily News Egypt.",
   "more": [
    "L'ospedale Nasser, a Khan Yunis, è una delle principali strutture sanitarie della Striscia di Gaza e ha subito più volte danni durante il conflitto tra Israele e Hamas. Il diritto internazionale umanitario prevede protezioni speciali per ospedali e personale medico anche in tempo di guerra."
   ],
