   "id": "zc8866b3f",
   "sez": "mondo",
   "titolo": "Venezuela, prigionieri politici e militari detenuti denunciano abusi",
   "orig": "Los presos políticos en Venezuela: mercancía humana",
   "lead": "Un editoriale di Confidencial torna sul tema dei prigionieri politici in Venezuela, descritti come 'merce umana', segnalando che è ormai il quindicesimo o sedicesimo articolo dedicato al tema negli ultimi quattro anni dall'autore, sempre nella speranza che fosse l'ultimo. Separatamente, più di 150 militari detenuti in Venezuela hanno denunciato violazioni al giusto processo e annunciato una protesta indefinita nel carcere di Ramo Verde, secondo una lettera resa pubblica dai loro familiari. Lo riferisce Confidencial.",
   "more": [
    "Il Venezuela è accusato da anni da organizzazioni umanitarie e governi internazionali di detenere prigionieri politici, oppositori e militari sospettati di slealtà verso il governo, spesso denunciando condizioni di detenzione difficili e processi irregolari."
   ],
