   "sez": "cultura",
   "titolo": "Il regista Fábio Silva racconta nel suo primo documentario le origini capoverdiane",
   "orig": "Fábio Silva, realizador: a questão de não ser tão negro como seria expectável",
   "lead": "Il regista Fábio Silva, figlio di genitori capoverdiani cresciuto in Portogallo, presenta il suo primo documentario biografico 'O Sangue da Aliança', che racconta il rapporto con la madre dopo la separazione dei genitori, in vista della prima mondiale ad Amsterdam. Nel film il regista affronta anche la questione identitaria legata al non essere percepito come 'sufficientemente nero' nonostante le sue origini capoverdiane, ed esprime l'auspicio di una maggiore presenza della diaspora africana nel cinema portoghese. Lo riferisce Público.",
   "more": [
    "Capo Verde è un arcipelago africano ex colonia portoghese, con una forte comunità di immigrati e discendenti in Portogallo. Il tema dell'identità dei portoghesi di origine africana è sempre più presente nel dibattito culturale e cinematografico del Paese."
   ],
